175	static uint64_t monotonic_us(void)
176	{
177	  struct timespec now;
178	
179	  if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
180	    {
181	      return 0;
182	    }
183	
184	  return (uint64_t)now.tv_sec * 1000000 + now.tv_nsec / 1000;
185	}
