574	/****************************************************************************
575	 * Name: page_event_cb
576	 *
577	 * Description:
578	 *   容器手势处理。四个阶段照官方 watch_v9 的 mainmenu_cell_page_event_cb()：
579	 *
580	 *     PRESSED   关掉 SCROLLABLE，停掉正在跑的吸附动画，接管滚动
581	 *     PRESSING  累加位移，超过 scroll_limit 才算真滚动（防误触）
582	 *     RELEASED  恢复 SCROLLABLE，交回 LVGL 做吸附
583	 *     （位移的实际应用在 refr_start_cb 里）
584	 *
585	 ****************************************************************************/
586	
587	static void page_event_cb(lv_event_t *e)
588	{
589	  lv_event_code_t code = lv_event_get_code(e);
590	
591	  if (code == LV_EVENT_PRESSED)
592	    {
593	      /* 接管滚动：禁掉 LVGL 自带的，并掐掉可能在跑的吸附动画，
594	       * 否则动画会和手指位移打架。
595	       */
596	
597	      lv_obj_remove_flag(g_app.page, LV_OBJ_FLAG_SCROLLABLE);
598	      lv_anim_delete(g_app.page, NULL);
599	      memset(&g_app.perf, 0, sizeof(g_app.perf));
600	    }
601	  else if (code == LV_EVENT_PRESSING)
602	    {
603	      lv_indev_t *indev = lv_indev_active();
604	      lv_point_t vect;
605	
606	      if (indev == NULL)
607	        {
608	          return;
609	        }
610	
611	      /* 本帧的手指位移增量 */
612	
613	      lv_indev_get_vect(indev, &vect);
614	
615	      perf_record(monotonic_us(),
616	                  &g_app.perf.first_input_us,
617	                  &g_app.perf.last_input_us,
618	                  &g_app.perf.input_events,
619	                  &g_app.perf.max_input_gap_us);
620	
621	      g_app.scroll_sum.x += vect.x;
622	      g_app.scroll_sum.y += vect.y;
623	
624	      /* 超过 scroll_limit 才认定为滚动，避免点按被当成滑动。
625	       * 一旦认定就保持，否则手指停顿会中断滚动。
626	       */
627	
628	      if (LV_ABS(g_app.scroll_sum.y) > SCROLL_LIMIT ||
629	          LV_ABS(g_app.scroll_sum.x) > SCROLL_LIMIT ||
630	          g_app.scroll_actived)
631	        {
632	          g_app.scroll_actived = true;
633	
634	          /* 标脏，触发下一次渲染 —— 实际位移在 refr_start_cb 里应用 */
635	
636	          lv_obj_invalidate(g_app.page);
637	        }
638	    }
639	  else if (code == LV_EVENT_RELEASED ||
640	           code == LV_EVENT_PRESS_LOST ||
641	           code == LV_EVENT_CLICKED)
642	    {
643	      /* 交回 LVGL：恢复 SCROLLABLE 后 snap 会把最近的卡片吸附到中心 */
644	
645	      lv_obj_add_flag(g_app.page, LV_OBJ_FLAG_SCROLLABLE);
646	
647	      if (g_app.scroll_actived)
648	        {
649	          lv_obj_scroll_to_view(nearest_card(), LV_ANIM_ON);
650	        }
651	
652	      perf_print();
653	      g_app.scroll_actived = false;
654	      g_app.scroll_sum.x = 0;
655	      g_app.scroll_sum.y = 0;
656	    }
657	}
